// ---- Suporte multi-ano ----
// SCHEDULES guarda, por ano, { data: [...], holidays: {...} }.
// Começa só com o ano embutido (2026); anos importados via planilha (admin)
// são carregados do servidor em loadSchedules() e podem sobrescrever
// integralmente um ano já existente ou adicionar anos novos.
const BUILTIN_SCHEDULES = { '2026': { data: DATA_2026, holidays: HOLIDAYS_2026 } };
let SCHEDULES = { '2026': { data: DATA_2026, holidays: HOLIDAYS_2026 } };
let currentYear = '2026';

function availableYears(){
  return Object.keys(SCHEDULES).sort();
}
function curData(){ return (SCHEDULES[currentYear] && SCHEDULES[currentYear].data) || []; }
function curHolidays(){ return (SCHEDULES[currentYear] && SCHEDULES[currentYear].holidays) || {}; }

function pickDefaultYear(){
  const years = availableYears();
  if(years.length === 0) return '2026';
  const thisYear = String(getToday().getFullYear());
  if(years.includes(thisYear)) return thisYear;
  return years[years.length - 1];
}

async function loadSchedules(){
  try{
    const r = await fetch('/api/schedule');
    if(!r.ok) throw new Error('bad response');
    const uploaded = await r.json(); // { "2027": {data, holidays}, ... }
    SCHEDULES = { ...BUILTIN_SCHEDULES, ...uploaded };
  }catch(e){
    SCHEDULES = { ...BUILTIN_SCHEDULES };
  }
  currentYear = pickDefaultYear();
}

function getToday(){ const n=new Date(); return new Date(n.getFullYear(),n.getMonth(),n.getDate()); }

const PERSON_COLORS = {
  'Bruno': 'var(--bruno)',
  'Estanis': 'var(--estanis)',
  'Pedro': 'var(--pedro)',
  'Vitor': 'var(--vitor)',
};
const PERSON_COLOR_HEX = {
  'Bruno': '#0D9488',
  'Estanis': '#7C3AED',
  'Pedro': '#DB2777',
  'Vitor': '#B45309',
};

const TITULARES = Object.keys(PERSON_COLOR_HEX);
let ALL_PEOPLE = [];
function computeAllPeople(){
  const set = new Set(TITULARES);
  curData().forEach(r => { if(r.backup) set.add(r.backup); });
  // inclui qualquer pessoa que já apareça em uma troca/substituição salva
  Object.entries(curOverrides()).forEach(([key, o]) => {
    if(!curData().find(r => r.sabado === key)) return;
    if(o && o.titular) set.add(o.titular);
    if(o && o.backup) set.add(o.backup);
  });
  ALL_PEOPLE = [...set];
}

// overridesByYear: { "2026": { "<sabado-iso>": {titular,backup,motivo,original_titular,original_backup,ts} }, ... }
let overridesByYear = {};
let storageAvailable = true;
let adminUser = sessionStorage.getItem('plantao-admin-user') || '';
let adminKey = sessionStorage.getItem('plantao-admin-key') || '';

function curOverrides(){ return overridesByYear[currentYear] || {}; }

async function loadOverrides(){
  try{
    const r = await fetch('/api/overrides');
    if(!r.ok) throw new Error('bad response');
    const raw = await r.json();
    const keys = Object.keys(raw || {});
    const looksLegacyFlat = keys.length > 0 && !/^\d{4}$/.test(keys[0]);
    overridesByYear = looksLegacyFlat ? { '2026': raw } : (raw || {});
  }catch(e){
    overridesByYear = {};
    storageAvailable = false;
  }
}

function promptLogin(errorMsg){
  return new Promise((resolve) => {
    const overlay = document.getElementById('loginOverlay');
    const box = document.getElementById('loginBox');
    box.innerHTML = `
      <h3>Login de administrador</h3>
      <div class="modal-sub">Necessário só para salvar trocas na escala — visualizar não precisa.</div>
      ${errorMsg ? `<div class="modal-error" style="color:var(--today); font-size:11px; margin-bottom:10px;">⚠ ${errorMsg}</div>` : ''}
      <label class="field-label">Usuário</label>
      <input type="text" id="loginUser" autocomplete="username">
      <label class="field-label">Senha</label>
      <input type="password" id="loginPass" autocomplete="current-password">
      <div class="modal-actions">
        <div></div>
        <div style="display:flex; gap:8px;">
          <button class="btn btn-ghost" id="loginCancel">cancelar</button>
          <button class="btn btn-primary" id="loginSubmit">entrar</button>
        </div>
      </div>
    `;
    overlay.classList.add('show');
    box.querySelector('#loginUser').focus();

    const finish = (val) => { overlay.classList.remove('show'); resolve(val); };
    box.querySelector('#loginCancel').addEventListener('click', () => finish(null));
    const submit = () => {
      const user = box.querySelector('#loginUser').value.trim();
      const pass = box.querySelector('#loginPass').value;
      finish({ user, pass });
    };
    box.querySelector('#loginSubmit').addEventListener('click', submit);
    box.querySelector('#loginPass').addEventListener('keydown', (e) => { if(e.key === 'Enter') submit(); });
  });
}
document.getElementById('loginOverlay').addEventListener('click', (e) => {
  if(e.target.id === 'loginOverlay') e.currentTarget.classList.remove('show');
});

// newOverridesByYear: objeto COMPLETO { "<ano>": {...} } — não só o ano atual.
async function apiSaveOverrides(newOverridesByYear){
  let user = adminUser, key = adminKey;
  let errorMsg = null;

  for(let attempt = 0; attempt < 3; attempt++){
    if(!user || !key){
      const creds = await promptLogin(errorMsg);
      if(!creds) return { ok:false, error:'Login cancelado.' };
      user = creds.user;
      key = creds.pass;
      errorMsg = null;
    }
    try{
      const r = await fetch('/api/overrides', {
        method: 'POST',
        headers: {'Content-Type': 'application/json', 'x-admin-user': user, 'x-admin-key': key},
        body: JSON.stringify(newOverridesByYear)
      });
      if(r.status === 401){
        user = ''; key = '';
        adminUser = ''; adminKey = '';
        sessionStorage.removeItem('plantao-admin-user');
        sessionStorage.removeItem('plantao-admin-key');
        errorMsg = 'Usuário ou senha incorretos.';
        continue;
      }
      if(!r.ok){
        let detail = '';
        try{ const j = await r.json(); detail = j.error || ''; }catch(_e){}
        return { ok:false, error: detail ? `Erro do servidor: ${detail}` : `Não deu para conectar ao servidor (status ${r.status}). A troca não foi salva.` };
      }
      adminUser = user; adminKey = key;
      sessionStorage.setItem('plantao-admin-user', user);
      sessionStorage.setItem('plantao-admin-key', key);
      overridesByYear = newOverridesByYear;
      storageAvailable = true;
      return { ok:true };
    }catch(e){
      return { ok:false, error:'Não deu para conectar ao servidor (falha de rede). A troca não foi salva.' };
    }
  }
  return { ok:false, error:'Muitas tentativas incorretas. Tente novamente mais tarde.' };
}
